export type NabreChapter = number | "A" | "B" | "C" | "D" | "E" | "F";

/** exact: same verse content. partial: the target verse(s) contain more or less text
 * (verses split/merged). approximate: verse division differs; closest verse.
 * noCounterpart: the source verse has no equivalent text in the other edition;
 * the result points at the nearest preceding verse. */
export type MapQuality = "exact" | "partial" | "approximate";

export type MappedVerse = {
  chapter: number;
  verse: number;
  /** Set when the source verse spans several target verses (inclusive). */
  verseEnd?: number;
  quality: MapQuality;
  noCounterpart?: true;
};

export type NabreMapped = MappedVerse & { slug: DouaySlug };
export type DouayMapped = Omit<MappedVerse, "chapter"> & { book: NabreBookId; chapter: NabreChapter };

