const QUALITY: readonly MapQuality[] = ["exact", "partial", "approximate", "approximate"];
const ESTHER_LETTERS = ["A", "B", "C", "D", "E", "F"] as const;

function nabreChapterIndex(book: NabreBookId, chapter: NabreChapter): number | null {
  if (typeof chapter === "number") return Number.isInteger(chapter) ? chapter : null;
  if (book !== "esther") return null;
  const i = ESTHER_LETTERS.indexOf(chapter);
  return i < 0 ? null : 41 + i;
}

function nabreChapterLabel(book: NabreBookId, chapter: number): NabreChapter {
  if (book === "esther" && chapter >= 41 && chapter <= 46) return ESTHER_LETTERS[chapter - 41];
  return chapter;
}

function verseCount(table: readonly number[] | undefined, chapter: number): number {
  if (!table || !Number.isInteger(chapter) || chapter < 1) return 0;
  return table[chapter - 1] ?? 0;
}

function isValid(table: readonly number[] | undefined, chapter: number, verse: number): boolean {
  return Number.isInteger(verse) && verse >= 1 && verse <= verseCount(table, chapter);
}

function applyRules(
  rules: readonly Rule[] | undefined,
  chapter: number,
  verse: number,
  target: readonly number[] | undefined,
): MappedVerse | null {
  if (rules) {
    for (const r of rules) {
      if (r[0] > chapter) break;
      if (r[0] !== chapter || verse < r[1] || verse > r[2]) continue;
      const q = r[6];
      if (q === 3) {
        if (r[3] === 0) return null;
        return { chapter: r[3], verse: r[4], quality: "approximate", noCounterpart: true };
      }
      const out: MappedVerse = {
        chapter: r[3],
        verse: q === 0 ? r[4] + (verse - r[1]) : r[4],
        quality: QUALITY[q],
      };
      if (r[5]) out.verseEnd = r[5];
      return out;
    }
  }
  return isValid(target, chapter, verse) ? { chapter, verse, quality: "exact" } : null;
}

/** Number of chapters the site's Douay-Rheims source has for a book (e.g. malachias = 3). */
export function douayChapterCount(slug: DouaySlug): number {
  return DOUAY_VERSES[slug]?.length ?? 0;
}

/** Verses in a Douay-Rheims chapter (0 if the chapter does not exist). */
export function douayVerseCount(slug: DouaySlug, chapter: number): number {
  return verseCount(DOUAY_VERSES[slug], chapter);
}

/**
 * Max-chapter guard: latinprayer.org answers out-of-range chapters with another chapter
 * (e.g. /malachias/4.json returns chapter 3), so validate before fetching.
 */
export function isValidDouayChapter(slug: DouaySlug, chapter: number): boolean {
  return douayVerseCount(slug, chapter) > 0;
}

/** Clamp a requested chapter into 1..douayChapterCount(slug). */
export function clampDouayChapter(slug: DouaySlug, chapter: number): number {
  const max = douayChapterCount(slug);
  if (!Number.isFinite(chapter) || max === 0) return 1;
  return Math.min(Math.max(1, Math.trunc(chapter)), max);
}

export function nabreVerseCount(book: NabreBookId, chapter: NabreChapter): number {
  const c = nabreChapterIndex(book, chapter);
  return c === null ? 0 : verseCount(NABRE_VERSES[book], c);
}

export function isDouaySlug(slug: string): slug is DouaySlug {
  return Object.prototype.hasOwnProperty.call(DOUAY_VERSES, slug);
}

export function isNabreBookId(book: string): book is NabreBookId {
  return Object.prototype.hasOwnProperty.call(NABRE_VERSES, book);
}

/** Official (NABRE) reference -> where the same text is in the site's Douay-Rheims data. */
export function nabreToDouay(
  book: NabreBookId,
  chapter: NabreChapter,
  verse: number,
): NabreMapped | null {
  const c = nabreChapterIndex(book, chapter);
  if (c === null || !isValid(NABRE_VERSES[book], c, verse)) return null;
  const slug = NABRE_BOOK_TO_SLUG[book];
  const m = applyRules(NABRE_TO_DOUAY_RULES[book], c, verse, DOUAY_VERSES[slug]);
  return m ? { ...m, slug } : null;
}

/** Site Douay-Rheims reference -> official (NABRE) reference for display/search. */
export function douayToNabre(slug: DouaySlug, chapter: number, verse: number): DouayMapped | null {
  if (!isValid(DOUAY_VERSES[slug], chapter, verse)) return null;
  const book = SLUG_TO_NABRE_BOOK[slug];
  const m = applyRules(DOUAY_TO_NABRE_RULES[slug], chapter, verse, NABRE_VERSES[book]);
  if (!m) return null;
  return { ...m, book, chapter: nabreChapterLabel(book, m.chapter) };
}
